[
  {
    "pd_personal_consequence_anxiety": "my chest is tight just thinking about actually saying the words",
    "sys_consequence_reasoning": "I don't have children waiting on me"
  },
  {
    "pd_personal_consequence_anxiety": "screaming that I don't want to die on this island",
    "pd_decision_conflict": "That pull between what seems noble and what I actually want is tearing at me"
  },
  {
    "pd_personal_consequence_anxiety": "the thought of actually being left behind makes my stomach turn over",
    "pd_decision_conflict": "caught between wanting to do right by the group and not wanting to face"
  },
  {
    "pd_personal_consequence_anxiety": "feel a knot in my throat imagining actually watching that boat pull away without me"
  },
  {
    "pd_harm_distress": "Knowing I'd be choosing my own place on the boat over someone else's life leaves me unsettled",
    "sys_consequence_reasoning": "I have people depending on me"
  },
  {
    "pd_decision_conflict": "I feel this pull in two directions that won't resolve",
    "sys_consequence_reasoning": "I've lived a fuller life than some of the others here"
  },
  {
    "sys_fairness_reciprocity": "decided by chance... That feels fairer to me",
    "pd_personal_consequence_anxiety": "my own name gets picked isn't something I can think through without some dread"
  },
  {
    "pd_personal_consequence_anxiety": "a kind of grief for my own life"
  },
  {
    "pd_harm_distress": "feel this weight of knowing somebody will be left no matter what",
    "pd_decision_conflict": "a lot of conflicting pulls I haven't sorted through yet"
  },
  {
    "pd_personal_consequence_anxiety": "tightness in my chest thinking about the actual moment of the boat leaving without me",
    "sys_consequence_reasoning": "rather carry that than watch it forced onto someone younger"
  }
]
